package com.example.starter.slaughter.domain;

/**
 * 屠宰批次流转状态。
 */
public enum BatchStatus {

    /** 宰前申报已受理，待宰前检疫。 */
    DECLARED,
    /** 宰前检疫合格，6 小时（UTC）内未屠宰则失效，须重新申报。 */
    PRE_QUARANTINED,
    /** 宰前检疫不合格，禁止后续流转。 */
    QUARANTINE_REJECTED,
    /** 同步检验链已开启，尚未覆盖全部头只。 */
    INSPECTING,
    /** 同步检验完成，全部头只一一对应检验完毕，待判定分流。 */
    INSPECTED,
    /** 存在漏检头只，整批暂停流转。 */
    SUSPENDED,
    /** 判定分流完成，待无害化处理回执闭环与出厂核销。 */
    JUDGED,
    /** 出厂核销完成，终态。 */
    CHECKED_OUT
}

package com.example.starter.slaughter.domain;

/**
 * 头只判定分流类别。
 */
public enum JudgmentCategory {

    /** 合格：直接标识为普通可流通库存。 */
    QUALIFIED,
    /** 有条件食用：须标注高温处理并限定流通区域。 */
    CONDITIONAL,
    /** 化制：须取得化制类无害化处理回执闭环。 */
    RENDERED,
    /** 销毁：须取得销毁类无害化处理回执闭环。 */
    DESTROYED
}

package com.example.starter.slaughter.domain;

/**
 * 宰前检疫结论。
 */
public enum PreQuarantineResult {

    /** 检疫合格，可在 6 小时（UTC）有效期内屠宰。 */
    PASS,
    /** 检疫不合格，禁止屠宰。 */
    FAIL
}

package com.example.starter.slaughter.domain;

/**
 * 单头同步检验结果。
 */
public enum InspectionResult {

    /** 检验正常。 */
    NORMAL,
    /** 检验可疑，须经判定分流决定处置方式。 */
    SUSPECT
}

package com.example.starter.slaughter.domain;

/**
 * 同步检验链状态：同一批次同时刻只允许一条检验链。
 */
public enum ChainStatus {

    /** 检验链开启中，可继续登记头只检验结果。 */
    OPEN,
    /** 头只全部一一对应检验完毕，检验链关闭。 */
    COMPLETED
}

